curl -s -X POST http://127.0.0.1:3202/eval -H "Content-Type: application/json" -d '{
"code": "const V = bot.entity.position.constructor; const plan = [ {t:[11,88,56], r:[10,88,56], f:[1,0,0]}, {t:[11,88,57], r:[10,88,57], f:[1,0,0]}, {t:[12,88,54], r:[11,88,54], f:[1,0,0]}, {t:[12,88,55], r:[11,88,55], f:[1,0,0]}, {t:[13,88,55], r:[14,88,55], f:[-1,0,0]}, {t:[13,88,56], r:[14,88,56], f:[-1,0,0]}, {t:[12,88,57], r:[13,88,57], f:[-1,0,0]}, {t:[12,88,56], r:[13,88,56], f:[-1,0,0]} ]; const results=[]; for (const step of plan){ const targetPos = new V(step.t[0], step.t[1], step.t[2]); const refPos = new V(step.r[0], step.r[1], step.r[2]); const refBlock = bot.blockAt(refPos); let ok=false, err=null, attempts=0; for (attempts=1; attempts<=2 && !ok; attempts++){ try { const cobbleItem = bot.inventory.items().find(i=>i.name===\"cobblestone\"); if(!cobbleItem){ err=\"no cobblestone\"; break; } await bot.equip(cobbleItem.type, \"hand\"); await bot.placeBlock(refBlock, new V(step.f[0], step.f[1], step.f[2])); } catch(e){ err = e.message; } const check = bot.blockAt(targetPos); ok = check && check.name===\"cobblestone\"; } results.push({target: step.t, refName: refBlock?refBlock.name:null, ok, attempts, err: ok?null:err}); if(!ok) break; } return {results, cobbleLeft: (bot.inventory.items().find(i=>i.name===\"cobblestone\")||{count:0}).count};"
}'

